use anyhow::{bail, Context, Result};

/// Parses a port spec like `"8080,443,9000-9005"` into the full port list,
/// expanding `lo-hi` ranges inclusively.
pub fn parse_ports(spec: &str) -> Result<Vec<u16>> {
    let port = |s: &str| {
        s.trim()
            .parse::<u16>()
            .with_context(|| format!("invalid port {:?} in {:?}", s, spec))
    };
    let mut ports = Vec::new();
    for part in spec.split(',') {
        let part = part.trim();
        match part.split_once('-') {
            Some((lo, hi)) => {
                let (lo, hi) = (port(lo)?, port(hi)?);
                if lo > hi {
                    bail!("invalid range {:?}: start {} > end {}", part, lo, hi);
                }
                ports.extend(lo..=hi);
            }
            None => ports.push(port(part)?),
        }
    }
    Ok(ports)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_lists_and_ranges() {
        assert_eq!(
            parse_ports("8080,443,9000-9005").unwrap(),
            vec![8080, 443, 9000, 9001, 9002, 9003, 9004, 9005]
        );
    }

    #[test]
    fn tolerates_spaces() {
        assert_eq!(parse_ports("80, 443").unwrap(), vec![80, 443]);
    }

    #[test]
    fn rejects_bad_input() {
        for bad in ["", "99999", "10-5", "80-", "80-90-100", "8080,-443"] {
            assert!(parse_ports(bad).is_err(), "should reject {:?}", bad);
        }
    }
}
